mapper.update:
merge into T_TM_DAY_FINISH_QTY a USING (
select #{ITEM.orderNo,jdbcType=VARCHAR} order_no, #{ITEM.scheduleDate,jdbcType=DATE} SCHEDULE_DATE, #{ITEM.treadCode,jdbcType=VARCHAR} TREAD_CODE, #{ITEM.dayFinishQty,jdbcType=DOUBLE} day_finish_qty, #{ITEM.nightFinishQty,jdbcType=DOUBLE} night_finish_qty, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.order_no = b.order_no AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.day_finish_qty = NVL(b.day_finish_qty, 0), a.night_finish_qty = NVL(b.night_finish_qty, 0), a.update_by = b.create_by, a.update_time = sysdate WHEN NOT MATCHED THEN INSERT (a.id, a.order_no, a.schedule_date, a.TREAD_CODE, a.day_finish_qty, a.night_finish_qty, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_CX_FINISH_QTY.NEXTVAL, b.order_no, b.SCHEDULE_DATE, b.TREAD_CODE, NVL(b.day_finish_qty, 0), NVL(b.night_finish_qty, 0), b.create_by, sysdate, b.remark, '0')

